function AnalogStopwatch() {
  const minuteAngle = (2 / 30) * 360;
  const secondAngle = (14 / 60) * 360;

  return (
    <div className="rafiq-time-watch-card">
      <div
        className="rafiq-analog-watch"
        role="img"
        aria-label="ساعة إيقاف تناظرية تشير إلى دقيقتين و14 ثانية"
      >
        <svg viewBox="0 0 320 320" aria-hidden="true">
          <circle cx="160" cy="168" r="118" className="watch-shell" />

          {Array.from({ length: 60 }, (_, index) => {
            const angle = (index / 60) * Math.PI * 2 - Math.PI / 2;
            const inner = index % 5 === 0 ? 91 : 99;
            const outer = 108;
            return (
              <line
                key={`seconds-${index}`}
                x1={160 + Math.cos(angle) * inner}
                y1={168 + Math.sin(angle) * inner}
                x2={160 + Math.cos(angle) * outer}
                y2={168 + Math.sin(angle) * outer}
                className={index % 5 === 0 ? 'watch-tick is-major' : 'watch-tick'}
              />
            );
          })}

          {[0, 10, 20, 30, 40, 50].map((value, index) => {
            const angle = (index / 6) * Math.PI * 2 - Math.PI / 2;
            return (
              <text
                key={value}
                x={160 + Math.cos(angle) * 75}
                y={174 + Math.sin(angle) * 75}
                textAnchor="middle"
                className="watch-number"
              >
                {value}
              </text>
            );
          })}

          <circle cx="160" cy="168" r="50" className="minute-dial" />

          {Array.from({ length: 30 }, (_, index) => {
            const angle = (index / 30) * Math.PI * 2 - Math.PI / 2;
            const inner = index % 5 === 0 ? 36 : 40;
            const outer = 47;
            return (
              <line
                key={`minutes-${index}`}
                x1={160 + Math.cos(angle) * inner}
                y1={168 + Math.sin(angle) * inner}
                x2={160 + Math.cos(angle) * outer}
                y2={168 + Math.sin(angle) * outer}
                className={index % 5 === 0 ? 'minute-tick is-major' : 'minute-tick'}
              />
            );
          })}

          {[0, 5, 10, 15, 20, 25].map((value, index) => {
            const angle = (index / 6) * Math.PI * 2 - Math.PI / 2;
            return (
              <text
                key={value}
                x={160 + Math.cos(angle) * 28}
                y={172 + Math.sin(angle) * 28}
                textAnchor="middle"
                className="minute-number"
              >
                {value}
              </text>
            );
          })}

          <g transform={`rotate(${minuteAngle} 160 168)`}>
            <line x1="160" y1="168" x2="160" y2="136" className="minute-hand" />
          </g>
          <g transform={`rotate(${secondAngle} 160 168)`}>
            <line x1="160" y1="178" x2="160" y2="78" className="second-hand" />
          </g>

          <circle cx="160" cy="168" r="7" className="watch-pin" />
          <rect x="137" y="24" width="46" height="28" rx="8" className="watch-crown" />
        </svg>
      </div>

      <div className="rafiq-watch-explanation">
        <small>تناظرية</small>
        <strong>اقرأ العقربين من التدريج</strong>
        <span>
          <b>القرص الداخلي:</b> دقائق، وكل تقسيم = 1 دقيقة.
        </span>
        <span>
          <b>التدريج الخارجي:</b> ثوانٍ، وكل تقسيم = 1 ثانية.
        </span>
      </div>
    </div>
  );
}

