function TimingChallenge({
  mode,
  onComplete,
}: {
  readonly mode: TimingMode;
  readonly onComplete: (seconds: number) => void;
}) {
  const [phase, setPhase] = useState<TimingPhase>('idle');
  const [countdown, setCountdown] = useState(3);
  const [result, setResult] = useState<number | null>(null);
  const targetTimeRef = useRef(0);
  const timersRef = useRef<number[]>([]);

  function clearTimers() {
    timersRef.current.forEach((timer) => window.clearTimeout(timer));
    timersRef.current = [];
  }

  useEffect(() => clearTimers, []);

  function start() {
    clearTimers();
    setResult(null);

    if (mode === 'reactive') {
      setPhase('waiting');
      const timer = window.setTimeout(() => {
        targetTimeRef.current = performance.now();
        setPhase('target');
      }, 1200);
      timersRef.current.push(timer);
      return;
    }

    const now = performance.now();
    targetTimeRef.current = now + 1800;
    setCountdown(3);
    setPhase('countdown');
    [1, 2].forEach((step) => {
      const timer = window.setTimeout(() => setCountdown(3 - step), step * 600);
      timersRef.current.push(timer);
    });
    const targetTimer = window.setTimeout(() => {
      setCountdown(0);
      setPhase('target');
    }, 1800);
    timersRef.current.push(targetTimer);
  }

  function capture() {
    if (mode === 'reactive' && phase !== 'target') return;
    if (mode === 'predictive' && phase !== 'countdown' && phase !== 'target') return;

    const delta = Math.abs(performance.now() - targetTimeRef.current) / 1000;
    const seconds = Number(delta.toFixed(2));
    clearTimers();
    setResult(seconds);
    setPhase('done');
    onComplete(seconds);
  }

  const title = mode === 'reactive' ? 'A: انتظر العبور ثم استجب' : 'B: توقّع العبور بالعد التنازلي';
  const startLabel = mode === 'reactive' ? 'ابدأ تجربة رد الفعل' : 'ابدأ تجربة التوقع';

  return (
    <article
      className={
        mode === 'predictive' ? 'rafiq-timing-challenge is-predictive' : 'rafiq-timing-challenge'
      }
    >
      <header>
        <span>{mode === 'reactive' ? 'A' : 'B'}</span>
        <h4>{title}</h4>
      </header>
      <PendulumVisual predictive={mode === 'predictive'} compact />
      <div className="rafiq-timing-target">
        <span className={phase === 'target' ? 'is-live' : ''} />
        <strong>
          {phase === 'target'
            ? 'الآن'
            : phase === 'countdown'
              ? countdown
              : phase === 'waiting'
                ? 'راقب'
                : phase === 'done'
                  ? 'تم القياس'
                  : 'جاهز'}
        </strong>
      </div>
      <div className="rafiq-timing-actions">
        <button
          type="button"
          onClick={start}
          disabled={phase === 'waiting' || phase === 'countdown' || phase === 'target'}
        >
          {startLabel}
        </button>
        <button
          type="button"
          className="is-primary"
          onClick={capture}
          disabled={
            mode === 'reactive' ? phase !== 'target' : phase !== 'countdown' && phase !== 'target'
          }
        >
          اضغط عند العلامة
        </button>
      </div>
      {result !== null ? (
        <div className="rafiq-timing-result">
          فرق ضغطتك عن اللحظة المرجعية: <ScientificText text={`${result.toFixed(2)} ثانية`} />
        </div>
      ) : null}
    </article>
  );
}

function CountedPendulumVisual({
  runKey,
  running,
  onFullOscillation,
  onComplete,
}: {
  readonly runKey: number;
  readonly running: boolean;
  readonly onFullOscillation: () => void;
  readonly onComplete: () => void;
}) {
  const motionRef = useRef<SVGGElement | null>(null);

  useEffect(() => {
    const motion = motionRef.current;
    if (!motion) return;

    const handleIteration = () => onFullOscillation();
    const handleEnd = () => onComplete();

    motion.addEventListener('animationiteration', handleIteration);
    motion.addEventListener('animationend', handleEnd);

    return () => {
      motion.removeEventListener('animationiteration', handleIteration);
      motion.removeEventListener('animationend', handleEnd);
    };
  }, [onComplete, onFullOscillation, runKey]);

  return (
    <div className="rafiq-time-pendulum is-compact">
      <svg viewBox="0 0 360 240" role="img" aria-label="بندول يعد التأرجحات الكاملة فعليًا">
        <path d="M64 36 H296" stroke="#274e60" strokeWidth="12" strokeLinecap="round" />
        <path d="M180 36 V218" stroke="#6f8b98" strokeWidth="2.5" strokeDasharray="8 7" />
        <path
          d="M88 206 Q180 236 272 206"
          fill="none"
          stroke="#b8cbd2"
          strokeWidth="3"
          strokeDasharray="7 8"
        />
        <g
          ref={motionRef}
          key={runKey}
          data-testid="counted-pendulum-motion"
          className={
            running ? 'rafiq-counted-pendulum-moving is-running' : 'rafiq-counted-pendulum-moving'
          }
        >
          <line
            x1="180"
            y1="42"
            x2="180"
            y2="172"
            stroke="#365b69"
            strokeWidth="5"
            strokeLinecap="round"
          />
          <circle cx="180" cy="190" r="24" fill="#d5a13b" stroke="#a87516" strokeWidth="4" />
          <circle cx="171" cy="181" r="6" fill="#f5d77f" opacity=".85" />
        </g>
        <circle cx="180" cy="218" r="5" fill="#176a8a" />
        <text x="180" y="234" textAnchor="middle" fill="#476875" fontSize="13">
          موضع الاتزان
        </text>
        <text x="74" y="194" textAnchor="middle" fill="#65808b" fontSize="12">
          جانب
        </text>
        <text x="286" y="194" textAnchor="middle" fill="#65808b" fontSize="12">
          جانب
        </text>
      </svg>
    </div>
  );
}

function OscillationCounter({
  onCompletionChange,
}: {
  readonly onCompletionChange: (complete: boolean) => void;
}) {
  const [count, setCount] = useState(0);
  const [running, setRunning] = useState(false);
  const [runKey, setRunKey] = useState(0);

  function start() {
    setCount(0);
    onCompletionChange(false);
    setRunKey((current) => current + 1);
    setRunning(true);
  }

  function recordFullOscillation() {
    setCount((current) => Math.min(current + 1, 11));
  }

  function completeRun() {
    // animationend fires only after the twelfth full cycle has returned
    // to the starting side, so completion can be committed directly here.
    setRunning(false);
    setCount(12);
    onCompletionChange(true);
  }

  return (
    <div className="rafiq-oscillation-counter">
      <div className="rafiq-oscillation-counter-visual">
        <CountedPendulumVisual
          runKey={runKey}
          running={running}
          onFullOscillation={recordFullOscillation}
          onComplete={completeRun}
        />
        <div className="rafiq-counter-badge" aria-live="polite" aria-label="عداد التأرجحات الكاملة">
          <strong>{count}</strong>
          <span>/ 12 تأرجحًا كاملًا</span>
        </div>
      </div>
      <button type="button" onClick={start} disabled={running}>
        {running ? 'جاري العد…' : count === 12 ? 'أعد المشاهدة' : 'شغّل عدّ 12 تأرجحًا'}
      </button>
      <div className="rafiq-oscillation-sync-note">
        <strong>العد مرتبط بالحركة نفسها.</strong>
        <span>
          لا يزيد العداد إلا بعد ذهاب البندول إلى الطرف الآخر ثم عودته إلى نقطة البداية. عند اكتمال
          التأرجح الثاني عشر يظهر الزمن الكلي المسجل للحساب.
        </span>
      </div>
    </div>
  );
}

