function formatSignedSeconds(value: number) {
  const rounded = Number(value.toFixed(2));
  if (rounded === 0) return '0.00 ثانية';
  const sign = rounded > 0 ? '+' : '−';
  return `${sign}${Math.abs(rounded).toFixed(2)} ثانية`;
}

function ProtocolPlot() {
  const min = 1.0;
  const max = 1.65;
  const reference = STRATEGY_COMPARISON.referencePeriodSeconds;
  const x = (value: number) => `${((value - min) / (max - min)) * 100}%`;
  const ticks = [1.0, 1.2, 1.4, 1.6] as const;

  return (
    <div
      className="rafiq-protocol-plot"
      role="img"
      aria-label="مخطط يقارن قياس تأرجح واحد بقياس 16 تأرجحًا لبندول مرجعه 1.36 ثانية"
    >
      <div className="rafiq-protocol-axis">
        {ticks.map((value) => (
          <span key={value} style={{ left: x(value) }}>
            {value.toFixed(2)}
          </span>
        ))}
      </div>
      <div className="rafiq-protocol-reference" style={{ left: x(reference) }}>
        <span>المرجع 1.36 ثانية</span>
      </div>
      <div className="rafiq-protocol-row">
        <b>A</b>
        <div className="rafiq-protocol-track">
          {SINGLE_CYCLE_VALUES.map((value) => (
            <i
              key={value}
              className="is-a"
              style={{ left: x(value) }}
              title={`${value.toFixed(2)} ثانية`}
            />
          ))}
        </div>
        <span>تأرجح واحد</span>
      </div>
      <div className="rafiq-protocol-row">
        <b>B</b>
        <div className="rafiq-protocol-track">
          <i
            className="is-b"
            style={{ left: x(MANY_CYCLE_PERIOD_SECONDS) }}
            title={`${MANY_CYCLE_PERIOD_SECONDS.toFixed(2)} ثانية`}
          />
        </div>
        <span>16 دورة ثم القسمة</span>
      </div>
      <p>
        الطريقة A تعرض ثلاث محاولات لزمن قصير جدًا، بينما B تقيس مدة أطول ثم تقسمها على عدد الدورات
        الكاملة.
      </p>
    </div>
  );
}

